record.field:
body {
    font-family: 'Arial', sans-serif;
    color: #333;
    font-size: 11pt;
    line-height: 1.4;
}
.contract-container {
    padding: 40px;
    max-width: 800px;
    margin: 0 auto;
}
.header-logo {
    text-align: right;
    margin-bottom: 20px;
}
.contract-header h1 {
    color: #A0522D; /* BLG Red/Brown */
    font-size: 24px;
    margin-bottom: 5px;
}
.contract-header h2 {
    color: #666;
    font-size: 16px;
    font-weight: normal;
    margin-top: 0;
}
h3 {
    color: #A0522D;
    font-size: 14pt;
    margin-top: 25px;
    margin-bottom: 10px;
    font-weight: bold;
}
h4 {
    color: #A0522D;
    font-size: 11pt;
    margin-top: 15px;
    font-weight: bold;
    font-style: italic;
}
.contract-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
}
.contract-table th {
    border-top: 2px solid #A0522D;
    border-bottom: 2px solid #A0522D;
    padding: 10px;
    text-align: center;
    color: #333;
    font-weight: normal;
}
.contract-table td {
    padding: 10px;
    text-align: center;
    border-bottom: 1px solid #ddd;
}
.total-row td {
    border-top: 2px solid #A0522D;
    font-weight: bold;
    color: #A0522D;
}
.small-text {
    font-size: 9pt;
    font-style: italic;
    color: #555;
    text-align: justify;
}
.contract-footer {
    margin-top: 50px;
}
.signature-block {
    display: flex;
    justify-content: space-between;
    margin-top: 40px;
}
.signature-column {
    width: 45%;
    text-align: center;
}
.sig-title {
    color: #A0522D;
    font-weight: bold;
    margin-bottom: 5px;
}
.sig-placeholder {
    height: 100px;
    border: 1px dashed #ccc;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    margin-top: 10px;
}
.sig-image-container img {
    max-width: 200px;
    max-height: 100px;
}
